package com.edgeos.launcher; import android.app.*;import android.os.*;import android.graphics.*;import android.content.*;import android.view.*;import android.widget.*;import java.util.*;
public class AppLibraryActivity extends Activity{LinearLayout list;ArrayList<AppInfo> apps;public void onCreate(Bundle b){super.onCreate(b);show();}void show(){apps=AppRepository.load(this);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(20,28,20,20);root.setBackgroundColor(0xFF111318);TextView h=Ui.text(this,"App Library",30,Color.WHITE);h.setGravity(Gravity.LEFT);root.addView(h,new LinearLayout.LayoutParams(-1,70));GridLayout g=new GridLayout(this);g.setColumnCount(4);for(AppInfo a:apps){LinearLayout x=new LinearLayout(this);x.setOrientation(LinearLayout.VERTICAL);x.setGravity(Gravity.CENTER);ImageView iv=new ImageView(this);iv.setImageDrawable(a.icon);x.addView(iv,new LinearLayout.LayoutParams(90,70));TextView t=Ui.text(this,a.label,10,Color.WHITE);t.setSingleLine(true);x.addView(t,new LinearLayout.LayoutParams(90,35));x.setOnClickListener(v->{Intent i=getPackageManager().getLaunchIntentForPackage(a.pkg);if(i!=null)startActivity(i);});g.addView(x,new ViewGroup.LayoutParams(90,115));}ScrollView sc=new ScrollView(this);sc.addView(g);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));Button s=Ui.pill(this,"⚙  Settings");s.setOnClickListener(v->startActivity(new Intent(this,SettingsActivity.class)));root.addView(s,new LinearLayout.LayoutParams(-1,58));setContentView(root);}}
